 static DynamicCatalog ready()throws IOException{DynamicCatalog c=snapshot;DynamicCatalog.need(c!=null,"NOT_PREPARED");return c;}
 static int integer(HistoryBson.Value d,String k,int fallback)throws IOException{HistoryBson.Value v=d.get(k);return v==null?fallback:v.integer();}
 static boolean marked(byte[] card)throws IOException{try{if(extension!=null&&extension.marked(card))return true;}catch(Exception e){throw new IOException(e);}HistoryBson.Value d=HistoryBson.parse(card);if(d.get("q7WishPlanVersion")!=null)throw new IOException("Wish resolver not prepared");HistoryBson.Value v=d.get(MARK);if(v==null)return false;DynamicCatalog.need(v.integer()==1&&HistoryBson.required(d,"q7DynamicHash").string().equals(SHA256)&&HistoryBson.required(d,"q7DynamicPolicy").string().equals(DynamicSlotPlan.policyFor(HistoryBson.integer(d,"q7HistoryPool"))),"TAG_BINDING");return true;}
