   boolean ownedBefore=LocalResourceEngine.ownsHero(result.profile,spec.target);int piece=leaf.piece;
   if(leaf.kind.equals("memory")){DynamicTransition.Blessing blessing=spec.policy.equals(POLICY)?DynamicTransition.memory(spec.rules,ledger,leaf.id,piece,LocalResourceEngine.ownsHero(result.profile,leaf.id),ownedMask(result.profile,leaf.id),catalog.heroes.get(leaf.id).files,random):DynamicTransition.memoryArchive(spec.rules,ledger,leaf.id,piece,LocalResourceEngine.ownsHero(result.profile,leaf.id),ownedMask(result.profile,leaf.id),catalog.heroes.get(leaf.id).files,random);piece=blessing.piece;ledger=blessing.state;}
   byte[] resolved=BsonLite.withProfileString(card,"q7Kind",leaf.kind);resolved=BsonLite.withProfileInt(resolved,"q7Id",leaf.id);resolved=BsonLite.withProfileInt(resolved,"q7Count",leaf.count);resolved=BsonLite.withProfileInt(resolved,"q7Quality",leaf.quality);resolved=BsonLite.withProfileInt(resolved,"hero_file",piece);resolved=BsonLite.withProfileArray(resolved,"hero",leaf.kind.equals("hero")||leaf.kind.equals("memory")?Collections.singletonList(leaf.id):Collections.<Integer>emptyList());if(leaf.design()!=null)resolved=BsonLite.withProfileDocument(resolved,"q7Design",leaf.design());
   resolved=BsonLite.withProfileInt(resolved,"q7HistoryNormalRow",outer.source);resolved=BsonLite.withProfileInt(resolved,"q7HistoryRandomId",outer.target);resolved=BsonLite.withProfileInt(resolved,"q7HistoryCommonId",leaf.common);
   int currencyBefore=leaf.kind.equals("money")||leaf.kind.equals("summonCoin")?integer(HistoryBson.parse(result.profile),leaf.kind,0):0;
   byte[] output=LocalDrawEngine.reveal(result,catalog,resolved); // exact original primary grant once
   if(leaf.kind.equals("money")||leaf.kind.equals("summonCoin")){int delta=integer(HistoryBson.parse(result.profile),leaf.kind,0)-currencyBefore;DynamicCatalog.need(delta==leaf.count,"PRIMARY_CURRENCY_DELTA");output=BsonLite.withProfileArray(output,"item",Collections.singletonList(Arrays.asList(LocalResourceEngine.currencyItem(leaf.kind),delta)));}
   DynamicTransition.Step primary=DynamicTransition.primary(spec.rules,ledger,leaf.id,leaf.kind.equals("hero"),leaf.kind.equals("memory"));ledger=primary.state;Bonuses charge=new Bonuses(),jiaozhi=new Bonuses(),extra=new Bonuses();
   for(DynamicTransition.Threshold threshold:primary.grants)for(int cid:threshold.rewards()){grantCommon(c,result,catalog,cid,charge);Map<?,?> reward=DynamicCatalog.map(c.common.get(cid));if(reward.containsKey("hero"))for(Object hero:DynamicCatalog.list(reward.get("hero")))ledger=DynamicTransition.chargedHero(spec.rules,ledger,DynamicCatalog.num(hero));}
   DynamicTransition.Step jstep=DynamicTransition.settle(spec.rules,ledger);ledger=jstep.state;for(DynamicTransition.Threshold threshold:jstep.grants)for(int rid:threshold.rewards())grantCommon(c,result,catalog,pickCommon(c,rid,random),jiaozhi);
   if(!ownedBefore&&LocalResourceEngine.ownsHero(result.profile,spec.target))for(Map<?,?> reward:spec.extra)grantCommon(c,result,catalog,DynamicCatalog.num(reward.get("common")),extra);
